"""RFC-7807-style reporting for legacy VRL validation failures."""

from __future__ import annotations

_VALID_CODES = frozenset(
    (
        "E1001", "E1002", "E1003", "E1004", "E1005",
        "E2001", "E2002", "E2003", "E2004",
        "E3001", "E3002", "E3003", "E3004", "E3005", "E3006", "E3007",
        "E4001", "E4002", "E4003", "E4004",
        "E5001", "E5002", "E5003", "E5004", "E5005",
    )
)


def problem_details(errors: list[dict]) -> dict:
    """Convert collected legacy validation failures into a problem document."""
    for error in errors:
        if error["code"] not in _VALID_CODES:
            raise ValueError("Unknown legacy validation error code")

    blocked = any(error["severity"] == "BLOCK" for error in errors)

    return {
        "type": "https://meridian-crm.example/problems/validation",
        "title": "Legacy validation failed",
        "status": 422 if blocked else 200,
        "blocked": blocked,
        "errors": [
            {
                "code": error["code"],
                "message": error["message"],
                "severity": error["severity"],
            }
            for error in errors
        ],
    }
